#!/usr/bin/env python3
"""
Round 167m (culprits), 4 October 2026. Needs round 164m.

Mother Earth: no brown on the ground; the page asks for a fresh script.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 167m (4 October)\n\nNeeds round 164m. No tiles patch. app.js?v= bumped to 1006.\n\n- Owner: Mother Earth still way too brown, and it looked as if 164m had not\n  gone through. 164m was on main (51f7eb0); the page still asked for\n  app.js?v=1005, as it had for many rounds, so browsers could keep an older\n  copy of the script. index.html now asks for v=1006 (test: appVersion >=\n  1006). Other chats: bump past 1006 if you need a fresh load.\n- No brown left on the ground: MOTHER.stone's middle tones were taupe; now\n  cool pearl and silver, warm only at the very lightest; towns, roads, rail\n  and buildings cool greys; hillshade light a neutral pale. The closest\n  zooms' photograph is moved 50% toward the palette (was 35%), so street\n  level is less brown too. Plants, water and the violet sky unchanged.\n- Test: every stone, town, building and road colour has red at most 12 over\n  blue; bare ground's red and blue within 14.\n"]
DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round167m: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 164m" not in h.read_text(encoding="utf-8"):
        sys.exit("round167m: round 164m must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round167m: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round167m: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round167m: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
